@Composable fun LotDialog(ctx:Context,db:AppDb,date:String,close:()->Unit){var lot by remember{mutableStateOf("")};var code by remember{mutableStateOf("")};var email by remember{mutableStateOf("")};var note by remember{mutableStateOf("")};val list=db.lots(date);SimpleDialog("📧 Chốt lô / báo cáo",close){OutlinedTextField(lot,{lot=it},Modifier.fillMaxWidth(),label={Text("Số lô")});OutlinedTextField(code,{code=it},Modifier.fillMaxWidth(),label={Text("Mã hàng")});OutlinedTextField(email,{email=it},Modifier.fillMaxWidth(),label={Text("Email nhận")});OutlinedTextField(note,{note=it},Modifier.fillMaxWidth(),label={Text("Nội dung báo cáo")});Button(onClick={if(lot.isNotBlank()){db.addLot(LotRecord(0,date,lot,code,"CHƯA CHỐT",email,note));lot="";code="";email="";note=""}},Modifier.fillMaxWidth()){Text("Lưu lô")};list.forEach{x->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("• Lô ${x.lot} | ${x.code} | ${x.status}");if(x.note.isNotBlank())Text(x.note)};TextButton(onClick={sendEmail(ctx,x.emailTo,"Báo cáo hoàn thành lô ${x.lot}","BÁO CÁO HOÀN THÀNH LÔ\nLô: ${x.lot}\nMã: ${x.code}\nNgày: ${x.date}\n${x.note}")}){Text("Mail")}}}}}
@Composable fun MailDialog(ctx:Context,db:AppDb,date:String,close:()->Unit){var subject by remember{mutableStateOf("")};var sender by remember{mutableStateOf("")};var note by remember{mutableStateOf("")};val list=db.mails(date);SimpleDialog("✉️ Theo dõi mail",close){OutlinedTextField(subject,{subject=it},Modifier.fillMaxWidth(),label={Text("Tiêu đề mail")});OutlinedTextField(sender,{sender=it},Modifier.fillMaxWidth(),label={Text("Người gửi / bộ phận")});OutlinedTextField(note,{note=it},Modifier.fillMaxWidth(),label={Text("Nội dung cần xử lý")});Button(onClick={if(subject.isNotBlank()){db.addMail(MailRecord(0,date,subject,sender,"CHƯA XỬ LÝ",note));subject="";sender="";note=""}},Modifier.fillMaxWidth()){Text("Lưu mail cần xử lý")};list.forEach{x->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("• ${x.subject}");Text("${x.sender} | ${x.status}");if(x.note.isNotBlank())Text(x.note)};OutlinedButton(onClick={sendEmail(ctx,"",x.subject,"Mail cần xử lý: ${x.subject}\nTừ: ${x.sender}\n${x.note}")}){Text("Mở mail")}}}}}

@Composable fun SimpleDialog(title:String,close:()->Unit,content:@Composable ColumnScope.()->Unit){AlertDialog(onDismissRequest=close,title={Text(title)},text={Column(Modifier.fillMaxWidth(),verticalArrangement=Arrangement.spacedBy(6.dp),content=content)},confirmButton={TextButton(onClick=close){Text("Đóng")}})}
@Composable fun HistoryScreen(db:AppDb,shift:String,refresh:Int){val dates=remember(refresh){db.historyDates()};var chosen by remember{mutableStateOf<String?>(null)};Column(Modifier.fillMaxSize().padding(12.dp)){Text("📅 Lịch sử",style=MaterialTheme.typography.headlineSmall);LazyColumn{items(dates){d->TextButton(onClick={chosen=d}){Text(d)}}}};chosen?.let{d->val ts=db.tasks(d,shift);AlertDialog(onDismissRequest={chosen=null},title={Text("$d • $shift")},text={Column{Text("Hoàn thành: ${ts.count{it.status=="HOÀN THÀNH"}}/18");Text("Có vấn đề: ${ts.count{it.problem}}");ts.filter{it.status!="HOÀN THÀNH"}.forEach{x->Text("• ${x.number}. ${x.title}: ${x.status}")}}},confirmButton={TextButton(onClick={chosen=null}){Text("Đóng")}})}}
@Composable fun OverviewScreen(tasks:List<DailyTask>,todos:List<Todo>,shift:String,overdue:Int,dueToday:Int){Column(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Tổng quan",style=MaterialTheme.typography.headlineSmall);Stat("Ca",shift);Stat("Hoàn thành","${tasks.count{it.status=="HOÀN THÀNH"}}/18");Stat("Đang làm","${tasks.count{it.status=="ĐANG LÀM"}}");Stat("Tồn đọng","${todos.count{it.status!="HOÀN THÀNH"}}");Stat("Đến hạn hôm nay","$dueToday");Stat("Quá hạn","$overdue")}}
